import subprocess, os, tempfile, shutil, re
ORIG="/workspace/executable"; NEW="/tmp/new_executable"
def normalize(s, td):
    return re.sub(r"thread 'main' \(\d+\)", "thread 'main' (XXX)", s).replace(td, "XXX")
def make_env():
    td=tempfile.mkdtemp()
    home=os.path.join(td,"home"); xdg_data=os.path.join(td,"data"); xdg_config=os.path.join(td,"config")
    os.makedirs(home); os.makedirs(xdg_data); os.makedirs(xdg_config)
    env=os.environ.copy(); env["HOME"]=home; env["XDG_DATA_HOME"]=xdg_data; env["XDG_CONFIG_HOME"]=xdg_config; env["XDG_DATA_DIRS"]=xdg_data; env["XDG_CONFIG_DIRS"]=xdg_config
    return td,env,home,xdg_data,xdg_config

def test_seq(initial_mimeapps, steps):
    td1,env1,home1,xdg_data1,xdg_config1=make_env()
    td2,env2,home2,xdg_data2,xdg_config2=make_env()
    for (td,env,home,xdg_data,xdg_config) in [(td1,env1,home1,xdg_data1,xdg_config1),(td2,env2,home2,xdg_data2,xdg_config2)]:
        apps=os.path.join(xdg_data,"applications"); os.makedirs(apps, exist_ok=True)
        for n in ["a.desktop","b.desktop"]:
            open(os.path.join(apps,n),"w").write(f"[Desktop Entry]\nName={n}\nExec=echo {n} %f\nType=Application\nMimeType=text/plain;\n")
        open(os.path.join(apps,"bad.desktop"),"w").write("invalid")
        os.makedirs(os.path.join(xdg_data,"mime"),exist_ok=True)
        open(os.path.join(xdg_data,"mime","globs"),"w").write("text/plain:*.txt\n")
        open(os.path.join(xdg_config,"mimeapps.list"),"w").write(initial_mimeapps)
    for args in steps:
        r1=subprocess.run([ORIG]+args, capture_output=True, text=True, env=env1, cwd=home1)
        r2=subprocess.run([NEW]+args, capture_output=True, text=True, env=env2, cwd=home2)
        out1=normalize(r1.stdout, td1); err1=normalize(r1.stderr, td1)
        out2=normalize(r2.stdout, td2); err2=normalize(r2.stderr, td2)
        try: c1=open(os.path.join(xdg_config1,"mimeapps.list")).read()
        except: c1="<missing>"
        try: c2=open(os.path.join(xdg_config2,"mimeapps.list")).read()
        except: c2="<missing>"
        match=(out1==out2 and err1==err2 and r1.returncode==r2.returncode and c1==c2)
        print(f"{'PASS' if match else 'FAIL'} init:{repr(initial_mimeapps[:60])} {args} RC:{r1.returncode}/{r2.returncode}")
        if not match:
