            if err1!=err2: print(f"  ERR o:{repr(err1[:500])} n:{repr(err2[:500])}")
            if c1!=c2: print(f"  FILE o:{repr(c1[:800])} n:{repr(c2[:800])}")
    shutil.rmtree(td1); shutil.rmtree(td2)

